gdscript
extends CharacterBody2D
class_name Enemy

@export var spec: EnemySpec

# fallback if spec is null (and also used by EnemyDrops module)
@export var item_pickup_scene: PackedScene
@export_range(0.0, 1.0, 0.01) var drop_chance: float = 0.25
@export var drop_pool_prefixes: PackedStringArray = ["conduit_"]
@export var drop_fallback_to_all: bool = false
@export var drop_amount_min: int = 1
@export var drop_amount_max: int = 1
@export var drop_instance_roll: bool = false
@export var drop_rarity_min: int = 0
@export var drop_rarity_max: int = 0
@export var drop_force_polarity: int = 0
@export var pickup_delay: float = 0.25
@export var drop_spawn_radius: float = 18.0

@export var speed: float = 150.0
@export var max_hp: float = 50.0
@export var knockback_decay: float = 2200.0

@export var debug_hits: bool = false
@export var debug_drops: bool = false

# ------------------------------------------------------------
# Dumb AI "unstuck" (LOS blocked -> find doorway / slide around cover)
# ------------------------------------------------------------
@export_group("AI - Unstuck")
@export var unstuck_enabled: bool = true
@export var unstuck_probe_dist: float = 56.0         # how far we raycast to check "free move"
@export var unstuck_flip_time: float = 2.0           # how often to flip wall-follow side if stuck
@export var unstuck_min_dist_progress: float = 6.0   # if we don't get closer by this much, consider "stuck"

# If you keep these at 0, we will auto-pull from EnemySenses.cover_mask()
@export var los_block_mask_override: int = 0
@export var move_block_mask_override: int = 0

# Runtime
var hp: float = 0.0
var player: Node2D = null
var dead: bool = false
var stun_time: float = 0.0
var knockback_vel: Vector2 = Vector2.ZERO

# Elite
var is_elite: bool = false

# Shared movement helpers
var _orbit_angle: float = 0.0
var _base_speed: float = 0.0

# Temporary speed buff (Herald)
var _speed_mul: float = 1.0
var _speed_mul_time: float = 0.0

# Unstuck state
var _wall_following: bool = false
var _wall_side: int = 1 # +1 or -1
var _wall_timer: float = 0.0
var _last_dist_to_player: float = 999999.0
var _stuck_timer: float = 0.0

# Computed masks (so we don't guess your layer setup wrong)
var _los_mask: int = 0
var _move_mask: int = 0

# Modules
var _drops: EnemyDrops = EnemyDrops.new()
var _senses: EnemySenses = EnemySenses.new()
var _leech: EnemyLeech = EnemyLeech.new()
var _herald: EnemyHerald = EnemyHerald.new()
var _tactical: EnemyTactical = EnemyTactical.new()
var _charge: EnemyCharge = EnemyCharge.new()
var _shooter: EnemyShooter = EnemyShooter.new()
var _summoner: EnemySummoner = EnemySummoner.new()
var _bomber: EnemyBomber = EnemyBomber.new()
var _splitter: EnemySplitter = EnemySplitter.new()
var _sniper: EnemySniper = EnemySniper.new()

var _life: EnemyLifecycle = EnemyLifecycle.new()
var _init: EnemyInit = EnemyInit.new()


func _ready() -> void:
	# Boot: applies spec, sets hp/player, visuals, hitbox signals, module setup
	_init.setup(self, _drops, _senses, _leech, _herald, _tactical, _charge, _shooter, _life)
	_init.boot()

	# Modules not wired inside EnemyInit (or you want explicit control here)
	_summoner.setup(self)
	_bomber.setup(self)
	_splitter.setup(self)
	_sniper.setup(self)

	# IMPORTANT: ensure lifecycle knows about bomber/splitter modules
	_life.setup(self, _drops, _bomber, _splitter)

	_refresh_unstuck_masks()


func _exit_tree() -> void:
	# important: sniper telegraph nodes live in current_scene, so free them on despawn
	if _sniper != null:
		_sniper.cleanup()


func _physics_process(delta: float) -> void:
	# Acquire player if needed
	if player == null or not is_instance_valid(player):
		player = get_tree().get_first_node_in_group("player") as Node2D

	# Knockback decay
	if knockback_vel != Vector2.ZERO:
		knockback_vel = knockback_vel.move_toward(Vector2.ZERO, knockback_decay * delta)

	# Module ticks
	_shooter.tick(delta)
	_charge.tick(delta)
	_summoner.tick(delta)
	_sniper.tick(delta)
	_herald.tick(delta)
	_tactical.tick(delta)

	# Speed buff timer (Herald)
	if _speed_mul_time > 0.0:
		_speed_mul_time = maxf(_speed_mul_time - delta, 0.0)
		if _speed_mul_time <= 0.0:
			_speed_mul = 1.0

	# Stun handling
	if stun_time > 0.0:
		stun_time = maxf(stun_time - delta, 0.0)
		velocity = knockback_vel
		move_and_slide()
		return

	if player == null:
		velocity = knockback_vel
		move_and_slide()
		return

	# Charge override (windup/dash) owned by EnemyCharge
	if _charge.step_override(delta):
		velocity = _charge.override_velocity() + knockback_vel
		move_and_slide()
		return

	# Basic vectors
	var dvec: Vector2 = (player.global_position - global_position)
	var dist: float = dvec.length()
	var to_player: Vector2 = (dvec / dist) if dist > 0.001 else Vector2.ZERO

	# IMPORTANT: allow “Elite = Tactical movement” while still running sniper attack logic
	# If this enemy’s base AI is SNIPER, always run sniper.brain once for side-effects (windup/fire/telegraph).
	var base_is_sniper: bool = (spec != null and spec.ai == EnemySpec.AI.SNIPER)
	var sniper_move: Vector2 = Vector2.ZERO
	var sniper_mul: float = 1.0

	if base_is_sniper:
		sniper_move = _sniper.brain(to_player, dist, _spd())
		sniper_mul = _sniper.windup_mul()

	var chase: Vector2 = Vector2.ZERO
	var ai: int = _get_active_ai()

	match ai:
		EnemySpec.AI.CHASE:
			chase = to_player * _spd()

		EnemySpec.AI.ORBIT:
			chase = _orbit_move(delta)

		EnemySpec.AI.RANGED:
			chase = _ranged_brain(to_player, dist)

		EnemySpec.AI.CHARGE:
			chase = _charge.brain(to_player, dist)

		EnemySpec.AI.BOMBER:
			chase = _bomber.brain(to_player, dist, _spd())

		EnemySpec.AI.SUMMONER:
			chase = _summoner.brain(to_player, dist, _spd())

		EnemySpec.AI.SPLITTER:
			chase = to_player * _spd()

		EnemySpec.AI.TACTICAL:
			chase = _tactical.brain(to_player, dist) * sniper_mul

		EnemySpec.AI.LEECH:
			chase = to_player * _spd()

		EnemySpec.AI.HERALD:
			chase = _herald.brain(to_player, dist)

		EnemySpec.AI.SNIPER:
			chase = sniper_move

		_:
			chase = to_player * _spd()

	# ------------------------------------------------------------
	# Unstuck layer: cheap pathing around walls/doors without navmesh
	# ------------------------------------------------------------
	if unstuck_enabled and _should_apply_unstuck(ai) and to_player != Vector2.ZERO:
		chase = _unstuck_adjust(delta, chase, to_player, dist)

	velocity = chase + knockback_vel
	move_and_slide()


func _get_active_ai() -> int:
	if spec == null:
		return EnemySpec.AI.CHASE
	if is_elite and spec.elite_ai_override >= 0:
		return spec.elite_ai_override
	return spec.ai


func _spd() -> float:
	return _base_speed * _speed_mul


func _orbit_move(delta: float) -> Vector2:
	if spec == null:
		return Vector2.ZERO

	_orbit_angle += spec.orbit_turn_speed * delta
	var target: Vector2 = player.global_position + Vector2.RIGHT.rotated(_orbit_angle) * spec.orbit_radius
	var v: Vector2 = (target - global_position)
	if v.length_squared() < 0.001:
		return Vector2.ZERO
	return v.normalized() * _spd()


func _ranged_brain(to_player: Vector2, dist: float) -> Vector2:
	if spec == null:
		return to_player * _spd()

	var desired: Vector2 = _shooter.kite_move(
		to_player,
		dist,
		_spd(),
		spec.preferred_range,
		spec.range_tolerance,
		spec.strafe_strength,
		1.0,
		1.0
	)

	_shooter.shoot_if_ready(to_player)
	return desired


# ------------------------------------------------------------
# Unstuck logic
# ------------------------------------------------------------
func _refresh_unstuck_masks() -> void:
	var cover: int = 0
	if _senses != null:
		cover = int(_senses.cover_mask())

	# LOS blockers
	if los_block_mask_override != 0:
		_los_mask = los_block_mask_override
	else:
		_los_mask = cover

	# Movement blockers (we include anything that blocks LOS, plus World layer 1 just in case walls are only on World)
	if move_block_mask_override != 0:
		_move_mask = move_block_mask_override
	else:
		_move_mask = _los_mask | (1 << (1 - 1)) # include layer 1

	# If still somehow 0, fallback to layer 1 so raycasts hit something
	if _los_mask == 0:
		_los_mask = (1 << (1 - 1))
	if _move_mask == 0:
		_move_mask = (1 << (1 - 1))


func _should_apply_unstuck(ai: int) -> bool:
	# Keep these exactly as they are:
	if ai == EnemySpec.AI.CHARGE:
		return false
	if ai == EnemySpec.AI.SNIPER:
		return false
	return true


func _unstuck_adjust(delta: float, desired: Vector2, to_player: Vector2, dist: float) -> Vector2:
	# Only do this if LOS is blocked by cover/world
	if not _is_los_blocked():
		_wall_following = false
		_wall_timer = 0.0
		_stuck_timer = 0.0
		_last_dist_to_player = dist
		return desired

	# Track "are we getting closer?"
	var progress: float = (_last_dist_to_player - dist)
	_last_dist_to_player = dist

	if progress < unstuck_min_dist_progress * delta:
		_stuck_timer += delta
	else:
		_stuck_timer = maxf(_stuck_timer - delta, 0.0)

	# If we're stuck for a bit, flip side more aggressively
	if _stuck_timer > 0.6:
		_wall_timer += delta
		if _wall_timer >= unstuck_flip_time:
			_wall_timer = 0.0
			_wall_side *= -1
	else:
		_wall_timer = maxf(_wall_timer - delta, 0.0)

	var desired_dir: Vector2 = desired.normalized()
	if desired_dir == Vector2.ZERO:
		desired_dir = to_player
	if desired_dir == Vector2.ZERO:
		return desired

	# 1) Try a few candidate directions (this finds doors/corridors)
	var best_dir: Vector2 = Vector2.ZERO
	var best_score: float = -999999.0

	var angles := PackedFloat32Array([0.0, 0.45, -0.45, 0.90, -0.90, 1.35, -1.35])
	for a in angles:
		var dir := desired_dir.rotated(a)
		if dir == Vector2.ZERO:
			continue
		if _ray_hits_blocker(global_position, global_position + dir * unstuck_probe_dist):
			continue

		# Score: prefer forward-ish directions, with small bias toward player
		var s: float = dir.dot(desired_dir) * 1.0 + dir.dot(to_player) * 0.35
		# Bias by wall side when stuck (helps pick consistent turn around corners)
		var side_bias: float = signf(Vector2(-desired_dir.y, desired_dir.x).dot(dir)) * float(_wall_side) * 0.08
		s += side_bias

		if s > best_score:
			best_score = s
			best_dir = dir

	if best_dir != Vector2.ZERO:
		_wall_following = false
		return best_dir.normalized() * maxf(desired.length(), _spd())

	# 2) If all probes are blocked, wall-follow: slide along the surface normal
	var hit: Dictionary = _ray_hit(global_position, global_position + desired_dir * unstuck_probe_dist, _move_mask)
	if hit.is_empty():
		return desired

	var nrm: Vector2 = Vector2.ZERO
	if hit.has("normal"):
		nrm = hit["normal"]
	if nrm == Vector2.ZERO:
		nrm = Vector2(-desired_dir.y, desired_dir.x)

	var tangent: Vector2 = Vector2(-nrm.y, nrm.x)
	if _wall_side < 0:
		tangent = -tangent
	if tangent.dot(desired_dir) < 0.0:
		tangent = -tangent

	_wall_following = true
	return tangent.normalized() * maxf(desired.length(), _spd())


func _is_los_blocked() -> bool:
	if player == null or not is_instance_valid(player):
		return false
	var hit: Dictionary = _ray_hit(global_position, player.global_position, _los_mask)
	return not hit.is_empty()


func _ray_hits_blocker(a: Vector2, b: Vector2) -> bool:
	var hit: Dictionary = _ray_hit(a, b, _move_mask)
	return not hit.is_empty()


func _ray_hit(from_pos: Vector2, to_pos: Vector2, mask: int) -> Dictionary:
	var space_state: PhysicsDirectSpaceState2D = get_world_2d().direct_space_state
	var q: PhysicsRayQueryParameters2D = PhysicsRayQueryParameters2D.create(from_pos, to_pos)
	q.collision_mask = mask
	q.exclude = [get_rid()]
	return space_state.intersect_ray(q)


# -----------------------
# Elite
# -----------------------
func make_elite() -> void:
	if spec == null or is_elite:
		return

	is_elite = true
	max_hp *= spec.elite_hp_mult
	hp = max_hp

	speed *= spec.elite_speed_mult
	_base_speed = speed

	var spr: CanvasItem = get_node_or_null("Sprite2D") as CanvasItem
	if spr != null:
		spr.modulate = spec.elite_tint


# -----------------------
# Effects / CC
# -----------------------
func apply_knockback(force: Vector2) -> void:
	knockback_vel += force


func apply_stun(seconds: float) -> void:
	stun_time = maxf(stun_time, seconds)


func apply_speed_buff(mult: float, duration: float) -> void:
	if mult <= 1.0 or duration <= 0.0:
		return
	_speed_mul = maxf(_speed_mul, mult)
	_speed_mul_time = maxf(_speed_mul_time, duration)


# -----------------------
# Hitbox -> Leech
# -----------------------
func _on_hitbox_area_entered(a: Area2D) -> void:
	_leech.on_hitbox_area_entered(a)


func _on_hitbox_area_exited(a: Area2D) -> void:
	_leech.on_hitbox_area_exited(a)


# -----------------------
# Damage -> Lifecycle
# -----------------------
func take_damage(amount: float, source: Node = null) -> void:
	_life.take_damage(amount, source)


# -----------------------
# Optional helpers (public, no underscore => no linter whining)
# -----------------------
func has_los_to_player() -> bool:
	return _senses.has_los_to_player()

func cover_mask() -> int:
	return _senses.cover_mask()

func ray_clear(a: Vector2, b: Vector2) -> bool:
	return _senses.ray_clear(a, b)

func point_blocked(p: Vector2) -> bool:
	return _senses.point_blocked(p)
Why this fixes your screenshot-case
If the door is around a corner, the old “only wall-hug when hit” can loop.
This version will probe multiple directions and pick the best open one → it will naturally pick the corridor/door direction even if it can’t “see” you yet.
It also forces masks to include Layer 1 so your AI rays don’t miss walls if your cover bodies only had World collision set.
If they STILL get stuck after this

Then 99% it’s one of these:

The door gap is physically too small for your enemy capsule
Your wall collision is only on an Area2D (overlap) instead of StaticBody2D / CollisionShape2D body collision
Your enemy CharacterBody2D collision mask doesn’t include world/walls

But try this file first — this one usually kills the “room stuck” problem completely without pathfinding.

ChatGPT said:

Got it — if they “still get stuck” even with the LOS-probe stuff, then what’s happening is usually one of these two:

They sometimes spawn partially inside a wall (chunk walls are everywhere now). Once a CharacterBody2D starts overlapped, “dumb steering” can look like it’s trying but never escapes.

Your “dumb pathing” needs a real wall-follow (Bug algorithm) that can handle doors around corners (local probing often fails when the opening isn’t within the probe radius).

So I’m going to give you a full enemy.gd replacement that adds:

Spawn de-penetration (if it spawns in/inside a wall, it relocates nearby to a free spot)
Bug wall-follow navigation (when LOS is blocked, it follows the wall edge until it finds a way out)

No navmesh, no hardpaths.

✅ Step-by-step (do exactly this)
1) Replace res://core/actors/enemy/enemy.gd with the full file below

Just paste it over your current one.

2) In the Enemy scene inspector (optional but recommended)

Set these (on the Enemy node, since they’re @export):

unstuck_probe_dist = 120 (or even 160)
unstuck_flip_time = 1.2
3) Important: make sure your walls are Bodies (StaticBody2D) not only Areas

Enemies collide with bodies. Areas don’t block movement.

