gdscript
extends CharacterBody2D
class_name Enemy

@export var spec: EnemySpec

# fallback if spec is null (and also used by EnemyDrops module)
@export var item_pickup_scene: PackedScene
@export_range(0.0, 1.0, 0.01) var drop_chance: float = 0.25
@export var drop_pool_prefixes: PackedStringArray = ["conduit_"]
@export var drop_fallback_to_all: bool = false
@export var drop_amount_min: int = 1
@export var drop_amount_max: int = 1
@export var drop_instance_roll: bool = false
@export var drop_rarity_min: int = 0
@export var drop_rarity_max: int = 0
@export var drop_force_polarity: int = 0
@export var pickup_delay: float = 0.25
@export var drop_spawn_radius: float = 18.0

@export var speed: float = 150.0
@export var max_hp: float = 50.0
@export var knockback_decay: float = 2200.0

@export var debug_hits: bool = false
@export var debug_drops: bool = false

# ------------------------------------------------------------
# "Dumb but not stupid" navigation
# ------------------------------------------------------------
@export_group("AI - Unstuck / Bug Nav")
@export var unstuck_enabled: bool = true
@export var unstuck_probe_dist: float = 120.0        # probe forward for free space / corners / doors
@export var unstuck_wall_sensor: float = 44.0        # probe sideways to keep hugging wall
@export var unstuck_flip_time: float = 1.2           # how often to flip side when stuck
@export var unstuck_min_move: float = 6.0            # px per second considered "moving"

# If 0, we auto-use EnemySenses.cover_mask()
@export var los_block_mask_override: int = 0
@export var move_block_mask_override: int = 0

# If spawn happens inside a wall (common now), shove out
@export_group("AI - Spawn Safety")
@export var spawn_escape_enabled: bool = true
@export var spawn_escape_radius: float = 160.0
@export var spawn_escape_tries: int = 40

# Runtime
var hp: float = 0.0
var player: Node2D = null
var dead: bool = false
var stun_time: float = 0.0
var knockback_vel: Vector2 = Vector2.ZERO

# Elite
var is_elite: bool = false

# Shared movement helpers
var _orbit_angle: float = 0.0
var _base_speed: float = 0.0

# Temporary speed buff (Herald)
var _speed_mul: float = 1.0
var _speed_mul_time: float = 0.0

# Bug-nav state
var _bug_mode: int = 0 # 0 = direct, 1 = wall-follow
var _bug_side: int = 1 # +1 or -1
var _bug_timer: float = 0.0
var _bug_last_pos: Vector2 = Vector2.ZERO
var _bug_stuck_time: float = 0.0
var _bug_wall_normal: Vector2 = Vector2.ZERO

# Computed masks
var _los_mask: int = 0
var _move_mask: int = 0

# Modules
var _drops: EnemyDrops = EnemyDrops.new()
var _senses: EnemySenses = EnemySenses.new()
var _leech: EnemyLeech = EnemyLeech.new()
var _herald: EnemyHerald = EnemyHerald.new()
var _tactical: EnemyTactical = EnemyTactical.new()
var _charge: EnemyCharge = EnemyCharge.new()
var _shooter: EnemyShooter = EnemyShooter.new()
var _summoner: EnemySummoner = EnemySummoner.new()
var _bomber: EnemyBomber = EnemyBomber.new()
var _splitter: EnemySplitter = EnemySplitter.new()
var _sniper: EnemySniper = EnemySniper.new()

var _life: EnemyLifecycle = EnemyLifecycle.new()
var _init: EnemyInit = EnemyInit.new()


func _ready() -> void:
	# Boot: applies spec, sets hp/player, visuals, hitbox signals, module setup
	_init.setup(self, _drops, _senses, _leech, _herald, _tactical, _charge, _shooter, _life)
	_init.boot()

	# Modules not wired inside EnemyInit (or you want explicit control here)
	_summoner.setup(self)
	_bomber.setup(self)
	_splitter.setup(self)
	_sniper.setup(self)

	# IMPORTANT: ensure lifecycle knows about bomber/splitter modules
	_life.setup(self, _drops, _bomber, _splitter)

	_refresh_nav_masks()

	_bug_last_pos = global_position

	if spawn_escape_enabled:
		_escape_if_inside_wall()


func _exit_tree() -> void:
	# important: sniper telegraph nodes live in current_scene, so free them on despawn
	if _sniper != null:
		_sniper.cleanup()


func _physics_process(delta: float) -> void:
	# Acquire player if needed
	if player == null or not is_instance_valid(player):
		player = get_tree().get_first_node_in_group("player") as Node2D

	# Knockback decay
	if knockback_vel != Vector2.ZERO:
		knockback_vel = knockback_vel.move_toward(Vector2.ZERO, knockback_decay * delta)

	# Module ticks
	_shooter.tick(delta)
	_charge.tick(delta)
	_summoner.tick(delta)
	_sniper.tick(delta)
	_herald.tick(delta)
	_tactical.tick(delta)

	# Speed buff timer (Herald)
	if _speed_mul_time > 0.0:
		_speed_mul_time = maxf(_speed_mul_time - delta, 0.0)
		if _speed_mul_time <= 0.0:
			_speed_mul = 1.0

	# Stun handling
	if stun_time > 0.0:
		stun_time = maxf(stun_time - delta, 0.0)
		velocity = knockback_vel
		move_and_slide()
		return

	if player == null:
		velocity = knockback_vel
		move_and_slide()
		return

	# Charge override (windup/dash) owned by EnemyCharge
	if _charge.step_override(delta):
		velocity = _charge.override_velocity() + knockback_vel
		move_and_slide()
		return

	# Basic vectors
	var dvec: Vector2 = (player.global_position - global_position)
	var dist: float = dvec.length()
	var to_player: Vector2 = (dvec / dist) if dist > 0.001 else Vector2.ZERO

	# Sniper special: keep its side-effects even if elite overrides movement
	var base_is_sniper: bool = (spec != null and spec.ai == EnemySpec.AI.SNIPER)
	var sniper_move: Vector2 = Vector2.ZERO
	var sniper_mul: float = 1.0
	if base_is_sniper:
		sniper_move = _sniper.brain(to_player, dist, _spd())
		sniper_mul = _sniper.windup_mul()

	var chase: Vector2 = Vector2.ZERO
	var ai: int = _get_active_ai()

	match ai:
		EnemySpec.AI.CHASE:
			chase = to_player * _spd()
		EnemySpec.AI.ORBIT:
			chase = _orbit_move(delta)
		EnemySpec.AI.RANGED:
			chase = _ranged_brain(to_player, dist)
		EnemySpec.AI.CHARGE:
			chase = _charge.brain(to_player, dist)
		EnemySpec.AI.BOMBER:
			chase = _bomber.brain(to_player, dist, _spd())
		EnemySpec.AI.SUMMONER:
			chase = _summoner.brain(to_player, dist, _spd())
		EnemySpec.AI.SPLITTER:
			chase = to_player * _spd()
		EnemySpec.AI.TACTICAL:
			chase = _tactical.brain(to_player, dist) * sniper_mul
		EnemySpec.AI.LEECH:
			chase = to_player * _spd()
		EnemySpec.AI.HERALD:
			chase = _herald.brain(to_player, dist)
		EnemySpec.AI.SNIPER:
			chase = sniper_move
		_:
			chase = to_player * _spd()

	# Bug-nav only for "dumb movers" (not charge/sniper dash)
	if unstuck_enabled and _should_use_bug(ai) and to_player != Vector2.ZERO:
		chase = _bug_nav(delta, chase, to_player)

	velocity = chase + knockback_vel
	move_and_slide()


func _get_active_ai() -> int:
	if spec == null:
		return EnemySpec.AI.CHASE
	if is_elite and spec.elite_ai_override >= 0:
		return spec.elite_ai_override
	return spec.ai


func _spd() -> float:
	return _base_speed * _speed_mul


func _orbit_move(delta: float) -> Vector2:
	if spec == null:
		return Vector2.ZERO

	_orbit_angle += spec.orbit_turn_speed * delta
	var target: Vector2 = player.global_position + Vector2.RIGHT.rotated(_orbit_angle) * spec.orbit_radius
	var v: Vector2 = (target - global_position)
	if v.length_squared() < 0.001:
		return Vector2.ZERO
	return v.normalized() * _spd()


func _ranged_brain(to_player: Vector2, dist: float) -> Vector2:
	if spec == null:
		return to_player * _spd()

	var desired: Vector2 = _shooter.kite_move(
		to_player,
		dist,
		_spd(),
		spec.preferred_range,
		spec.range_tolerance,
		spec.strafe_strength,
		1.0,
		1.0
	)

	_shooter.shoot_if_ready(to_player)
	return desired


# ------------------------------------------------------------
# Bug navigation (wall-follow) - works for rooms/doors/corners
# ------------------------------------------------------------
func _should_use_bug(ai: int) -> bool:
	if ai == EnemySpec.AI.CHARGE:
		return false
	if ai == EnemySpec.AI.SNIPER:
		return false
	return true


func _bug_nav(delta: float, desired: Vector2, to_player: Vector2) -> Vector2:
	# If LOS is clear -> go direct and reset bug mode
	if not _is_los_blocked():
		_bug_mode = 0
		_bug_timer = 0.0
		_bug_stuck_time = 0.0
		return desired

	# Movement progress tracking
	var moved: float = global_position.distance_to(_bug_last_pos)
	_bug_last_pos = global_position

	if moved < (unstuck_min_move * delta):
		_bug_stuck_time += delta
	else:
		_bug_stuck_time = maxf(_bug_stuck_time - delta, 0.0)

	_bug_timer += delta
	if _bug_timer >= unstuck_flip_time and _bug_stuck_time > 0.4:
		_bug_timer = 0.0
		_bug_side *= -1

	# Enter wall-follow if we are blocked and not already following
	if _bug_mode == 0:
		_bug_mode = 1
		_bug_timer = 0.0
		_bug_side = (1 if (randi() & 1) == 0 else -1)
		_bug_wall_normal = _estimate_wall_normal(to_player)

	# Wall-follow movement:
	# tangent is perpendicular to wall normal
	var nrm: Vector2 = _bug_wall_normal
	if nrm == Vector2.ZERO:
		nrm = Vector2(-to_player.y, to_player.x)

	var tangent: Vector2 = Vector2(-nrm.y, nrm.x)
	if _bug_side < 0:
		tangent = -tangent

	if tangent == Vector2.ZERO:
		tangent = Vector2(-to_player.y, to_player.x)

	# If tangent direction is blocked, flip
	if _ray_hits_blocker(global_position, global_position + tangent.normalized() * (unstuck_probe_dist * 0.6)):
		_bug_side *= -1
		tangent = -tangent

	# Update wall normal by probing "into" the wall (opposite of tangent)
	var into_wall: Vector2 = -tangent.normalized()
	var wh: Dictionary = _ray_hit(global_position, global_position + into_wall * unstuck_wall_sensor, _move_mask)
	if not wh.is_empty() and wh.has("normal"):
		var new_nrm: Vector2 = wh["normal"]
		if new_nrm != Vector2.ZERO:
			_bug_wall_normal = new_nrm

	# Try opportunistic escape: if we can move in a direction that is BOTH
	#  - not blocked immediately
	#  - more aligned toward the player than current tangent
	var best_dir: Vector2 = Vector2.ZERO
	var best_score: float = -999999.0
	var base_dir: Vector2 = desired.normalized()
	if base_dir == Vector2.ZERO:
		base_dir = to_player

	var angles := PackedFloat32Array([0.0, 0.35, -0.35, 0.70, -0.70, 1.05, -1.05])
	for a in angles:
		var dir: Vector2 = base_dir.rotated(a)
		if dir == Vector2.ZERO:
			continue
		if _ray_hits_blocker(global_position, global_position + dir * unstuck_probe_dist):
			continue

		# prefer directions that point to player, but allow "around corner"
		var sc: float = dir.dot(to_player) * 1.0 + dir.dot(base_dir) * 0.35
		if sc > best_score:
			best_score = sc
			best_dir = dir

	if best_dir != Vector2.ZERO and best_score > 0.25:
		# keep wall-follow state but allow leaving the wall when possible
		return best_dir.normalized() * maxf(desired.length(), _spd())

	# Default: continue wall-follow
	return tangent.normalized() * maxf(desired.length(), _spd())


func _estimate_wall_normal(to_player: Vector2) -> Vector2:
	# ray toward player to find the blocking surface normal
	var hit: Dictionary = _ray_hit(global_position, global_position + to_player * unstuck_probe_dist, _move_mask)
	if not hit.is_empty() and hit.has("normal"):
		var n: Vector2 = hit["normal"]
		if n != Vector2.ZERO:
			return n
	# fallback
	return Vector2(-to_player.y, to_player.x)


func _is_los_blocked() -> bool:
	if player == null or not is_instance_valid(player):
		return false
	var hit: Dictionary = _ray_hit(global_position, player.global_position, _los_mask)
	return not hit.is_empty()


func _ray_hits_blocker(a: Vector2, b: Vector2) -> bool:
	var hit: Dictionary = _ray_hit(a, b, _move_mask)
	return not hit.is_empty()


func _ray_hit(from_pos: Vector2, to_pos: Vector2, mask: int) -> Dictionary:
	var space_state: PhysicsDirectSpaceState2D = get_world_2d().direct_space_state
	var q: PhysicsRayQueryParameters2D = PhysicsRayQueryParameters2D.create(from_pos, to_pos)
	q.collision_mask = mask
	q.exclude = [get_rid()]
	return space_state.intersect_ray(q)


func _refresh_nav_masks() -> void:
	var cover: int = 0
	if _senses != null:
		cover = int(_senses.cover_mask())

	_los_mask = (los_block_mask_override if los_block_mask_override != 0 else cover)
	if _los_mask == 0:
		_los_mask = (1 << (1 - 1)) # fallback: World layer 1

	# movement blockers: LOS blockers + World layer 1 (walls often live there)
	_move_mask = (move_block_mask_override if move_block_mask_override != 0 else (_los_mask | (1 << (1 - 1))))
	if _move_mask == 0:
		_move_mask = (1 << (1 - 1))


# ------------------------------------------------------------
# Spawn escape (fixes: enemies "stuck in wall" forever)
# ------------------------------------------------------------
func _escape_if_inside_wall() -> void:
	if not _point_blocked(global_position):
		return

	for i in range(maxi(1, spawn_escape_tries)):
		var ang: float = randf() * TAU
		var r: float = lerpf(18.0, spawn_escape_radius, randf())
		var p: Vector2 = global_position + Vector2.RIGHT.rotated(ang) * r
		if not _point_blocked(p):
			global_position = p
			_bug_last_pos = global_position
			return


func _point_blocked(p: Vector2) -> bool:
	var space_state: PhysicsDirectSpaceState2D = get_world_2d().direct_space_state
	var q := PhysicsPointQueryParameters2D.new()
	q.position = p
	q.collision_mask = _move_mask
	q.collide_with_bodies = true
	q.collide_with_areas = true
	q.exclude = [get_rid()]
	var res: Array = space_state.intersect_point(q, 1)
	return not res.is_empty()


# -----------------------
# Elite
# -----------------------
func make_elite() -> void:
	if spec == null or is_elite:
		return

	is_elite = true
	max_hp *= spec.elite_hp_mult
	hp = max_hp

	speed *= spec.elite_speed_mult
	_base_speed = speed

	var spr: CanvasItem = get_node_or_null("Sprite2D") as CanvasItem
	if spr != null:
		spr.modulate = spec.elite_tint


# -----------------------
# Effects / CC
# -----------------------
func apply_knockback(force: Vector2) -> void:
	knockback_vel += force


func apply_stun(seconds: float) -> void:
	stun_time = maxf(stun_time, seconds)


func apply_speed_buff(mult: float, duration: float) -> void:
	if mult <= 1.0 or duration <= 0.0:
		return
	_speed_mul = maxf(_speed_mul, mult)
	_speed_mul_time = maxf(_speed_mul_time, duration)


# -----------------------
# Hitbox -> Leech
# -----------------------
func _on_hitbox_area_entered(a: Area2D) -> void:
	_leech.on_hitbox_area_entered(a)


func _on_hitbox_area_exited(a: Area2D) -> void:
	_leech.on_hitbox_area_exited(a)


# -----------------------
# Damage -> Lifecycle
# -----------------------
func take_damage(amount: float, source: Node = null) -> void:
	_life.take_damage(amount, source)


# -----------------------
# Optional helpers (public, no underscore => no linter whining)
# -----------------------
func has_los_to_player() -> bool:
	return _senses.has_los_to_player()

func cover_mask() -> int:
	return _senses.cover_mask()

func ray_clear(a: Vector2, b: Vector2) -> bool:
	return _senses.ray_clear(a, b)

func point_blocked(p: Vector2) -> bool:
	return _senses.point_blocked(p)
If they STILL get stuck after this (next likely culprit)

Then it’s not AI anymore — it’s spawning inside walls, or enemy collision mask doesn’t include the wall layer.

If you want, next step I’ll give you a full spawner.gd replacement that guarantees enemies never spawn inside cover/world (it does a shape-check and retries around the ring). That’s the other half of making this bulletproof.

ChatGPT said:

Yeah — that “vibrating” is a classic symptom of flip-flop steering (the AI keeps choosing left/right every frame because both look “equally blocked”), so it never commits to a direction long enough to actually go around the wall and find the door.

Let’s fix it the clean way for a “dumb” horde game:

✅ Keep them focused on the player
✅ If LOS is blocked, they pick a detour direction (left/right)
✅ They commit to it for a short time (so no jitter)
✅ If they aren’t making progress, they flip side and try again
✅ Also: if they spawn inside a wall, they teleport out (this happens a lot with chunk walls)

