gdscript
extends CharacterBody2D
class_name Enemy

@export var spec: EnemySpec

# fallback if spec is null (and also used by EnemyDrops module)
@export var item_pickup_scene: PackedScene
@export_range(0.0, 1.0, 0.01) var drop_chance: float = 0.25
@export var drop_pool_prefixes: PackedStringArray = ["conduit_"]
@export var drop_fallback_to_all: bool = false
@export var drop_amount_min: int = 1
@export var drop_amount_max: int = 1
@export var drop_instance_roll: bool = false
@export var drop_rarity_min: int = 0
@export var drop_rarity_max: int = 0
@export var drop_force_polarity: int = 0
@export var pickup_delay: float = 0.25
@export var drop_spawn_radius: float = 18.0

@export var speed: float = 150.0
@export var max_hp: float = 50.0
@export var knockback_decay: float = 2200.0

@export var debug_hits: bool = false
@export var debug_drops: bool = false

# ------------------------------------------------------------
# "Dumb but not stuck" wall detour
# ------------------------------------------------------------
@export_group("AI - Detour (LOS blocked)")
@export var detour_enabled: bool = true
@export var detour_probe_dist: float = 220.0        # how far we test a direction for being clear
@export var detour_reprobe_dist: float = 60.0       # small test to keep moving in detour
@export var detour_commit_time: float = 0.45        # seconds we commit to chosen detour (prevents vibration)
@export var detour_flip_stuck_time: float = 0.60    # if not moving for this long, flip side
@export var detour_min_move_px_per_sec: float = 10.0

# If you ever need to override the ray mask manually:
# 0 = auto (cover mask | world layer 1)
@export var move_block_mask_override: int = 0
@export var los_block_mask_override: int = 0

@export_group("AI - Spawn Safety")
@export var spawn_escape_enabled: bool = true
@export var spawn_escape_radius: float = 160.0
@export var spawn_escape_tries: int = 40

# Runtime
var hp: float = 0.0
var player: Node2D = null
var dead: bool = false
var stun_time: float = 0.0
var knockback_vel: Vector2 = Vector2.ZERO

# Elite
var is_elite: bool = false

# Shared movement helpers
var _orbit_angle: float = 0.0
var _base_speed: float = 0.0

# Temporary speed buff (Herald)
var _speed_mul: float = 1.0
var _speed_mul_time: float = 0.0

# Detour state
var _detour_dir: Vector2 = Vector2.ZERO
var _detour_time: float = 0.0
var _detour_side: int = 1
var _last_pos: Vector2 = Vector2.ZERO
var _stuck_time: float = 0.0

# Masks
var _move_mask: int = 0
var _los_mask: int = 0

# Modules
var _drops: EnemyDrops = EnemyDrops.new()
var _senses: EnemySenses = EnemySenses.new()
var _leech: EnemyLeech = EnemyLeech.new()
var _herald: EnemyHerald = EnemyHerald.new()
var _tactical: EnemyTactical = EnemyTactical.new()
var _charge: EnemyCharge = EnemyCharge.new()
var _shooter: EnemyShooter = EnemyShooter.new()
var _summoner: EnemySummoner = EnemySummoner.new()
var _bomber: EnemyBomber = EnemyBomber.new()
var _splitter: EnemySplitter = EnemySplitter.new()
var _sniper: EnemySniper = EnemySniper.new()

var _life: EnemyLifecycle = EnemyLifecycle.new()
var _init: EnemyInit = EnemyInit.new()


func _ready() -> void:
	# Boot: applies spec, sets hp/player, visuals, hitbox signals, module setup
	_init.setup(self, _drops, _senses, _leech, _herald, _tactical, _charge, _shooter, _life)
	_init.boot()

	# Modules not wired inside EnemyInit (or you want explicit control here)
	_summoner.setup(self)
	_bomber.setup(self)
	_splitter.setup(self)
	_sniper.setup(self)

	# IMPORTANT: ensure lifecycle knows about bomber/splitter modules
	_life.setup(self, _drops, _bomber, _splitter)

	_refresh_masks()
	_last_pos = global_position

	if spawn_escape_enabled:
		_escape_if_inside_wall()


func _exit_tree() -> void:
	# important: sniper telegraph nodes live in current_scene, so free them on despawn
	if _sniper != null:
		_sniper.cleanup()


func _physics_process(delta: float) -> void:
	# Acquire player if needed
	if player == null or not is_instance_valid(player):
		player = get_tree().get_first_node_in_group("player") as Node2D

	# Knockback decay
	if knockback_vel != Vector2.ZERO:
		knockback_vel = knockback_vel.move_toward(Vector2.ZERO, knockback_decay * delta)

	# Module ticks
	_shooter.tick(delta)
	_charge.tick(delta)
	_summoner.tick(delta)
	_sniper.tick(delta)
	_herald.tick(delta)
	_tactical.tick(delta)

	# Speed buff timer (Herald)
	if _speed_mul_time > 0.0:
		_speed_mul_time = maxf(_speed_mul_time - delta, 0.0)
		if _speed_mul_time <= 0.0:
			_speed_mul = 1.0

	# Stun handling
	if stun_time > 0.0:
		stun_time = maxf(stun_time - delta, 0.0)
		velocity = knockback_vel
		move_and_slide()
		return

	if player == null:
		velocity = knockback_vel
		move_and_slide()
		return

	# Charge override (windup/dash) owned by EnemyCharge
	if _charge.step_override(delta):
		velocity = _charge.override_velocity() + knockback_vel
		move_and_slide()
		return

	# Basic vectors
	var dvec: Vector2 = (player.global_position - global_position)
	var dist: float = dvec.length()
	var to_player: Vector2 = (dvec / dist) if dist > 0.001 else Vector2.ZERO

	# IMPORTANT: allow “Elite = Tactical movement” while still running sniper attack logic
	var base_is_sniper: bool = (spec != null and spec.ai == EnemySpec.AI.SNIPER)
	var sniper_move: Vector2 = Vector2.ZERO
	var sniper_mul: float = 1.0

	if base_is_sniper:
		sniper_move = _sniper.brain(to_player, dist, _spd())
		sniper_mul = _sniper.windup_mul()

	var chase: Vector2 = Vector2.ZERO
	var ai: int = _get_active_ai()

	match ai:
		EnemySpec.AI.CHASE:
			chase = to_player * _spd()

		EnemySpec.AI.ORBIT:
			chase = _orbit_move(delta)

		EnemySpec.AI.RANGED:
			chase = _ranged_brain(to_player, dist)

		EnemySpec.AI.CHARGE:
			chase = _charge.brain(to_player, dist)

		EnemySpec.AI.BOMBER:
			chase = _bomber.brain(to_player, dist, _spd())

		EnemySpec.AI.SUMMONER:
			chase = _summoner.brain(to_player, dist, _spd())

		EnemySpec.AI.SPLITTER:
			chase = to_player * _spd()

		EnemySpec.AI.TACTICAL:
			chase = _tactical.brain(to_player, dist) * sniper_mul

		EnemySpec.AI.LEECH:
			chase = to_player * _spd()

		EnemySpec.AI.HERALD:
			chase = _herald.brain(to_player, dist)

		EnemySpec.AI.SNIPER:
			chase = sniper_move

		_:
			chase = to_player * _spd()

	# Apply detour steering for “dumb movers” when LOS is blocked
	if detour_enabled and _should_detour(ai) and to_player != Vector2.ZERO:
		chase = _apply_detour(delta, chase, to_player)

	velocity = chase + knockback_vel
	move_and_slide()


func _get_active_ai() -> int:
	if spec == null:
		return EnemySpec.AI.CHASE
	if is_elite and spec.elite_ai_override >= 0:
		return spec.elite_ai_override
	return spec.ai


func _spd() -> float:
	return _base_speed * _speed_mul


func _orbit_move(delta: float) -> Vector2:
	if spec == null:
		return Vector2.ZERO

	_orbit_angle += spec.orbit_turn_speed * delta
	var target: Vector2 = player.global_position + Vector2.RIGHT.rotated(_orbit_angle) * spec.orbit_radius
	var v: Vector2 = (target - global_position)
	if v.length_squared() < 0.001:
		return Vector2.ZERO
	return v.normalized() * _spd()


func _ranged_brain(to_player: Vector2, dist: float) -> Vector2:
	if spec == null:
		return to_player * _spd()

	var desired: Vector2 = _shooter.kite_move(
		to_player,
		dist,
		_spd(),
		spec.preferred_range,
		spec.range_tolerance,
		spec.strafe_strength,
		1.0,
		1.0
	)

	_shooter.shoot_if_ready(to_player)
	return desired


# ------------------------------------------------------------
# Detour logic
# ------------------------------------------------------------
func _should_detour(ai: int) -> bool:
	# Don't mess with charge/sniper move
	if ai == EnemySpec.AI.CHARGE:
		return false
	if ai == EnemySpec.AI.SNIPER:
		return false
	return true


func _apply_detour(delta: float, desired: Vector2, to_player: Vector2) -> Vector2:
	# If LOS clear -> reset detour
	if _has_los_clear():
		_detour_dir = Vector2.ZERO
		_detour_time = 0.0
		_stuck_time = 0.0
		return desired

	# Track if we're actually moving (to avoid vibration lock)
	var moved: float = global_position.distance_to(_last_pos)
	_last_pos = global_position

	var min_move: float = detour_min_move_px_per_sec * delta
	if moved < min_move:
		_stuck_time += delta
	else:
		_stuck_time = maxf(_stuck_time - delta, 0.0)

	# If stuck too long -> flip side and force re-pick
	if _stuck_time >= detour_flip_stuck_time:
		_stuck_time = 0.0
		_detour_side *= -1
		_detour_time = 0.0
		_detour_dir = Vector2.ZERO

	# Tick detour timer
	if _detour_time > 0.0:
		_detour_time = maxf(_detour_time - delta, 0.0)

	# Need a new detour direction?
	if _detour_dir == Vector2.ZERO or _detour_time <= 0.0:
		_detour_dir = _pick_detour_dir(to_player)
		_detour_time = detour_commit_time

	# If our detour became blocked, repick immediately (but still commit after pick)
	if _detour_dir != Vector2.ZERO and not _dir_clear(_detour_dir, detour_reprobe_dist):
		_detour_dir = _pick_detour_dir(to_player)
		_detour_time = detour_commit_time

	if _detour_dir == Vector2.ZERO:
		return desired

	# Move at roughly same speed as "desired"
	var sp: float = desired.length()
	if sp <= 0.01:
		sp = _spd()
	return _detour_dir.normalized() * sp


func _pick_detour_dir(to_player: Vector2) -> Vector2:
	var base: Vector2 = to_player.normalized()
	if base == Vector2.ZERO:
		return Vector2.ZERO

	# We bias the search to one side first (commit), then try the other side.
	# This makes them “pick a wall and follow it” until they find a door/corner.
	var angles_deg: Array[float] = [
		float(_detour_side) * 90.0,
		float(_detour_side) * 60.0,
		float(_detour_side) * 120.0,
		float(_detour_side) * 35.0,
		float(_detour_side) * 145.0,
		0.0,
		float(-_detour_side) * 35.0,
		float(-_detour_side) * 60.0,
		float(-_detour_side) * 90.0,
		float(-_detour_side) * 120.0,
		float(-_detour_side) * 145.0
	]

	for a in angles_deg:
		var dir: Vector2 = base.rotated(deg_to_rad(a)).normalized()
		if dir == Vector2.ZERO:
			continue
		if _dir_clear(dir, detour_probe_dist):
			return dir

	# As a last resort, try a fully random direction (rare), helps if wedged
	var rand_dir: Vector2 = Vector2.RIGHT.rotated(randf() * TAU)
	if _dir_clear(rand_dir, detour_probe_dist * 0.6):
		return rand_dir

	return Vector2.ZERO


func _dir_clear(dir: Vector2, dist: float) -> bool:
	var a: Vector2 = global_position
	var b: Vector2 = global_position + dir.normalized() * dist
	return _ray_clear_mask(a, b, _move_mask)


func _has_los_clear() -> bool:
	if player == null or not is_instance_valid(player):
		return true
	return _ray_clear_mask(global_position, player.global_position, _los_mask)


func _ray_clear_mask(a: Vector2, b: Vector2, mask: int) -> bool:
	var space_state: PhysicsDirectSpaceState2D = get_world_2d().direct_space_state
	var q: PhysicsRayQueryParameters2D = PhysicsRayQueryParameters2D.create(a, b)
	q.collision_mask = mask
	q.exclude = [get_rid()]
	var hit: Dictionary = space_state.intersect_ray(q)
	return hit.is_empty()


func _refresh_masks() -> void:
	# We want:
	# - LOS blocked by cover + world
	# - movement blocked by cover + world
	var cover_mask_val: int = 0
	if _senses != null:
		cover_mask_val = int(_senses.cover_mask())

	var world_mask: int = (1 << (1 - 1)) # layer 1

	_los_mask = (los_block_mask_override if los_block_mask_override != 0 else (cover_mask_val | world_mask))
	_move_mask = (move_block_mask_override if move_block_mask_override != 0 else (cover_mask_val | world_mask))

	if _los_mask == 0:
		_los_mask = world_mask
	if _move_mask == 0:
		_move_mask = world_mask


func _escape_if_inside_wall() -> void:
	# If we spawned inside a wall, we’ll never get out with steering.
	# So we relocate to nearest free spot.
	if not _point_blocked_mask(global_position, _move_mask):
		return

	for i in range(maxi(1, spawn_escape_tries)):
		var ang: float = randf() * TAU
		var r: float = lerpf(20.0, spawn_escape_radius, randf())
		var p: Vector2 = global_position + Vector2.RIGHT.rotated(ang) * r
		if not _point_blocked_mask(p, _move_mask):
			global_position = p
			_last_pos = p
			return


func _point_blocked_mask(p: Vector2, mask: int) -> bool:
	var space_state: PhysicsDirectSpaceState2D = get_world_2d().direct_space_state
	var q := PhysicsPointQueryParameters2D.new()
	q.position = p
	q.collision_mask = mask
	q.collide_with_bodies = true
	q.collide_with_areas = true
	q.exclude = [get_rid()]
	var res: Array = space_state.intersect_point(q, 1)
	return not res.is_empty()


# -----------------------
# Elite
# -----------------------
func make_elite() -> void:
	if spec == null or is_elite:
		return

	is_elite = true
	max_hp *= spec.elite_hp_mult
	hp = max_hp

	speed *= spec.elite_speed_mult
	_base_speed = speed

	var spr: CanvasItem = get_node_or_null("Sprite2D") as CanvasItem
	if spr != null:
		spr.modulate = spec.elite_tint


# -----------------------
# Effects / CC
# -----------------------
func apply_knockback(force: Vector2) -> void:
	knockback_vel += force


func apply_stun(seconds: float) -> void:
	stun_time = maxf(stun_time, seconds)


func apply_speed_buff(mult: float, duration: float) -> void:
	if mult <= 1.0 or duration <= 0.0:
		return
	_speed_mul = maxf(_speed_mul, mult)
	_speed_mul_time = maxf(_speed_mul_time, duration)


# -----------------------
# Hitbox -> Leech
# -----------------------
func _on_hitbox_area_entered(a: Area2D) -> void:
	_leech.on_hitbox_area_entered(a)


func _on_hitbox_area_exited(a: Area2D) -> void:
	_leech.on_hitbox_area_exited(a)


# -----------------------
# Damage -> Lifecycle
# -----------------------
func take_damage(amount: float, source: Node = null) -> void:
	_life.take_damage(amount, source)


# -----------------------
# Optional helpers (public, no underscore => no linter whining)
# -----------------------
func has_los_to_player() -> bool:
	return _senses.has_los_to_player()

func cover_mask() -> int:
	return _senses.cover_mask()

func ray_clear(a: Vector2, b: Vector2) -> bool:
	return _senses.ray_clear(a, b)

func point_blocked(p: Vector2) -> bool:
	return _senses.point_blocked(p)
