gdscript
extends CharacterBody2D
class_name Enemy

@export var spec: EnemySpec

# fallback if spec is null (and also used by EnemyDrops module)
@export var item_pickup_scene: PackedScene
@export_range(0.0, 1.0, 0.01) var drop_chance: float = 0.25
@export var drop_pool_prefixes: PackedStringArray = ["conduit_"]
@export var drop_fallback_to_all: bool = false
@export var drop_amount_min: int = 1
@export var drop_amount_max: int = 1
@export var drop_instance_roll: bool = false
@export var drop_rarity_min: int = 0
@export var drop_rarity_max: int = 0
@export var drop_force_polarity: int = 0
@export var pickup_delay: float = 0.25
@export var drop_spawn_radius: float = 18.0

@export var speed: float = 150.0
@export var max_hp: float = 50.0
@export var knockback_decay: float = 2200.0

@export var debug_hits: bool = false
@export var debug_drops: bool = false

# ------------------------------------------------------------
# "Dumb but not stuck" obstacle navigation
# ------------------------------------------------------------
@export_group("AI - Wall Follow (No Navmesh)")
@export var wall_follow_enabled: bool = true
@export var wall_follow_commit_time: float = 0.55      # how long to commit to one side before reconsidering
@export var wall_follow_probe_dist: float = 56.0       # short probe in follow dir (corner handling)
@export var wall_follow_stuck_flip_time: float = 0.70  # if not moving, flip side
@export var wall_follow_min_move_px_per_sec: float = 12.0

@export_group("AI - Cover Layers")
@export var cover_full_layer: int = 9
@export var cover_window_layer: int = 10
@export var cover_half_layer: int = 11

# If you ever want to override masks manually (0 = auto)
@export var move_mask_override: int = 0
@export var los_mask_override: int = 0

@export_group("AI - Spawn Safety")
@export var spawn_escape_enabled: bool = true
@export var spawn_escape_radius: float = 160.0
@export var spawn_escape_tries: int = 40

# Runtime
var hp: float = 0.0
var player: Node2D = null
var dead: bool = false
var stun_time: float = 0.0
var knockback_vel: Vector2 = Vector2.ZERO

# Elite
var is_elite: bool = false

# Shared movement helpers
var _orbit_angle: float = 0.0
var _base_speed: float = 0.0

# Temporary speed buff (Herald)
var _speed_mul: float = 1.0
var _speed_mul_time: float = 0.0

# Wall-follow state
enum NavState { DIRECT, FOLLOW }
var _nav_state: int = NavState.DIRECT
var _nav_side: int = 1                 # 1 = left, -1 = right
var _nav_follow_dir: Vector2 = Vector2.ZERO
var _nav_commit: float = 0.0
var _nav_stuck: float = 0.0
var _nav_last_pos: Vector2 = Vector2.ZERO

# Masks
var _move_mask: int = 0
var _los_mask_melee: int = 0
var _los_mask_shooter: int = 0

# Modules
var _drops: EnemyDrops = EnemyDrops.new()
var _senses: EnemySenses = EnemySenses.new()
var _leech: EnemyLeech = EnemyLeech.new()
var _herald: EnemyHerald = EnemyHerald.new()
var _tactical: EnemyTactical = EnemyTactical.new()
var _charge: EnemyCharge = EnemyCharge.new()
var _shooter: EnemyShooter = EnemyShooter.new()
var _summoner: EnemySummoner = EnemySummoner.new()
var _bomber: EnemyBomber = EnemyBomber.new()
var _splitter: EnemySplitter = EnemySplitter.new()
var _sniper: EnemySniper = EnemySniper.new()

var _life: EnemyLifecycle = EnemyLifecycle.new()
var _init: EnemyInit = EnemyInit.new()


func _ready() -> void:
	# Boot: applies spec, sets hp/player, visuals, hitbox signals, module setup
	_init.setup(self, _drops, _senses, _leech, _herald, _tactical, _charge, _shooter, _life)
	_init.boot()

	# Modules not wired inside EnemyInit (or you want explicit control here)
	_summoner.setup(self)
	_bomber.setup(self)
	_splitter.setup(self)
	_sniper.setup(self)

	# IMPORTANT: ensure lifecycle knows about bomber/splitter modules
	_life.setup(self, _drops, _bomber, _splitter)

	_refresh_masks()
	_nav_last_pos = global_position

	if spawn_escape_enabled:
		_escape_if_inside_wall()


func _exit_tree() -> void:
	# important: sniper telegraph nodes live in current_scene, so free them on despawn
	if _sniper != null:
		_sniper.cleanup()


func _physics_process(delta: float) -> void:
	# Acquire player if needed
	if player == null or not is_instance_valid(player):
		player = get_tree().get_first_node_in_group("player") as Node2D

	# Knockback decay
	if knockback_vel != Vector2.ZERO:
		knockback_vel = knockback_vel.move_toward(Vector2.ZERO, knockback_decay * delta)

	# Module ticks
	_shooter.tick(delta)
	_charge.tick(delta)
	_summoner.tick(delta)
	_sniper.tick(delta)
	_herald.tick(delta)
	_tactical.tick(delta)

	# Speed buff timer (Herald)
	if _speed_mul_time > 0.0:
		_speed_mul_time = maxf(_speed_mul_time - delta, 0.0)
		if _speed_mul_time <= 0.0:
			_speed_mul = 1.0

	# Stun handling
	if stun_time > 0.0:
		stun_time = maxf(stun_time - delta, 0.0)
		velocity = knockback_vel
		move_and_slide()
		return

	if player == null:
		velocity = knockback_vel
		move_and_slide()
		return

	# Charge override (windup/dash) owned by EnemyCharge
	if _charge.step_override(delta):
		velocity = _charge.override_velocity() + knockback_vel
		move_and_slide()
		return

	# Basic vectors
	var dvec: Vector2 = (player.global_position - global_position)
	var dist: float = dvec.length()
	var to_player: Vector2 = (dvec / dist) if dist > 0.001 else Vector2.ZERO

	# Sniper always runs for side effects (telegraph/fire), even if elite overrides movement
	var base_is_sniper: bool = (spec != null and spec.ai == EnemySpec.AI.SNIPER)
	var sniper_move: Vector2 = Vector2.ZERO
	var sniper_mul: float = 1.0
	if base_is_sniper:
		sniper_move = _sniper.brain(to_player, dist, _spd())
		sniper_mul = _sniper.windup_mul()

	var chase: Vector2 = Vector2.ZERO
	var ai: int = _get_active_ai()

	match ai:
		EnemySpec.AI.CHASE:
			chase = to_player * _spd()

		EnemySpec.AI.ORBIT:
			chase = _orbit_move(delta)

		EnemySpec.AI.RANGED:
			chase = _ranged_brain(to_player, dist)

		EnemySpec.AI.CHARGE:
			chase = _charge.brain(to_player, dist)

		EnemySpec.AI.BOMBER:
			chase = _bomber.brain(to_player, dist, _spd())

		EnemySpec.AI.SUMMONER:
			chase = _summoner.brain(to_player, dist, _spd())

		EnemySpec.AI.SPLITTER:
			chase = to_player * _spd()

		EnemySpec.AI.TACTICAL:
			chase = _tactical.brain(to_player, dist) * sniper_mul

		EnemySpec.AI.LEECH:
			chase = to_player * _spd()

		EnemySpec.AI.HERALD:
			chase = _herald.brain(to_player, dist)

		EnemySpec.AI.SNIPER:
			chase = sniper_move

		_:
			chase = to_player * _spd()

	# ------------------------------------------------------------
	# Wall-follow override (ONLY when straight path is blocked)
	# ------------------------------------------------------------
	if wall_follow_enabled and to_player != Vector2.ZERO:
		var exclude: Array[RID] = _build_exclude_rids()

		# If straight movement line to player is blocked by cover, use wall-follow.
		var blocked: bool = not _ray_clear(global_position, player.global_position, _move_mask, exclude)

		# Optional: shooters can also “seek LOS” if full cover blocks shots.
		var is_shooter: bool = (ai == EnemySpec.AI.RANGED or ai == EnemySpec.AI.SNIPER)
		if is_shooter:
			var los_mask: int = (_los_mask_shooter if los_mask_override == 0 else los_mask_override)
			var los_ok: bool = _ray_clear(global_position, player.global_position, los_mask, exclude)
			# If LOS is blocked but movement isn't, still reposition via wall-follow (peek/door finding).
			if not los_ok:
				blocked = true

		if blocked:
			chase = _wall_follow_step(delta, player.global_position, _spd(), exclude)
		else:
			# direct path available => reset nav state
			_nav_state = NavState.DIRECT
			_nav_commit = 0.0
			_nav_follow_dir = Vector2.ZERO
			_nav_stuck = 0.0

	velocity = chase + knockback_vel
	move_and_slide()


func _get_active_ai() -> int:
	if spec == null:
		return EnemySpec.AI.CHASE
	if is_elite and spec.elite_ai_override >= 0:
		return spec.elite_ai_override
	return spec.ai


func _spd() -> float:
	return _base_speed * _speed_mul


func _orbit_move(delta: float) -> Vector2:
	if spec == null:
		return Vector2.ZERO

	_orbit_angle += spec.orbit_turn_speed * delta
	var target: Vector2 = player.global_position + Vector2.RIGHT.rotated(_orbit_angle) * spec.orbit_radius
	var v: Vector2 = (target - global_position)
	if v.length_squared() < 0.001:
		return Vector2.ZERO
	return v.normalized() * _spd()


func _ranged_brain(to_player: Vector2, dist: float) -> Vector2:
	if spec == null:
		return to_player * _spd()

	var desired: Vector2 = _shooter.kite_move(
		to_player,
		dist,
		_spd(),
		spec.preferred_range,
		spec.range_tolerance,
		spec.strafe_strength,
		1.0,
		1.0
	)

	_shooter.shoot_if_ready(to_player)
	return desired


# ------------------------------------------------------------
# Wall-follow navigation (Bug-style)
# ------------------------------------------------------------
func _wall_follow_step(delta: float, target_pos: Vector2, move_speed: float, exclude: Array[RID]) -> Vector2:
	# stuck detection
	var moved: float = global_position.distance_to(_nav_last_pos)
	_nav_last_pos = global_position

	var min_move: float = wall_follow_min_move_px_per_sec * delta
	if moved < min_move:
		_nav_stuck += delta
	else:
		_nav_stuck = maxf(_nav_stuck - delta, 0.0)

	if _nav_stuck >= wall_follow_stuck_flip_time:
		_nav_stuck = 0.0
		_nav_side *= -1
		_nav_commit = 0.0
		_nav_follow_dir = Vector2.ZERO
		_nav_state = NavState.FOLLOW

	# commit timer
	if _nav_commit > 0.0:
		_nav_commit = maxf(_nav_commit - delta, 0.0)

	# If direct line becomes clear, go direct
	if _ray_clear(global_position, target_pos, _move_mask, exclude):
		_nav_state = NavState.DIRECT
		_nav_follow_dir = Vector2.ZERO
		_nav_commit = 0.0
		var dir_direct: Vector2 = (target_pos - global_position).normalized()
		return dir_direct * move_speed

	# Blocked -> ensure FOLLOW state
	if _nav_state == NavState.DIRECT:
		_nav_state = NavState.FOLLOW
		_nav_commit = 0.0

	# Need to pick / refresh follow direction?
	if _nav_follow_dir == Vector2.ZERO or _nav_commit <= 0.0:
		_nav_follow_dir = _pick_follow_dir(target_pos, exclude)
		_nav_commit = wall_follow_commit_time

	# Corner handling: if moving along follow dir is blocked short-range, re-pick using a fresh normal
	if _nav_follow_dir != Vector2.ZERO:
		var probe_to: Vector2 = global_position + _nav_follow_dir * wall_follow_probe_dist
		if not _ray_clear(global_position, probe_to, _move_mask, exclude):
			_nav_follow_dir = _pick_follow_dir(target_pos, exclude)
			_nav_commit = wall_follow_commit_time

	if _nav_follow_dir == Vector2.ZERO:
		# last resort: still try something toward target
		var fallback: Vector2 = (target_pos - global_position).normalized()
		return fallback * move_speed

	return _nav_follow_dir.normalized() * move_speed


func _pick_follow_dir(target_pos: Vector2, exclude: Array[RID]) -> Vector2:
	# Ray to target gives us a wall normal; tangent to that normal is “follow wall”.
	var hit: Dictionary = _ray_hit(global_position, target_pos, _move_mask, exclude)
	var nrm: Vector2 = Vector2.ZERO
	if not hit.is_empty() and hit.has("normal"):
		nrm = hit["normal"] as Vector2

	# If we somehow got no normal, approximate
	if nrm == Vector2.ZERO:
		var to_t: Vector2 = (target_pos - global_position).normalized()
		if to_t == Vector2.ZERO:
			return Vector2.ZERO
		nrm = -to_t

	var tangent: Vector2 = nrm.rotated(float(_nav_side) * PI * 0.5).normalized()
	if tangent == Vector2.ZERO:
		return Vector2.ZERO

	# Prefer the tangent that actually moves us (probe forward)
	var probe_to: Vector2 = global_position + tangent * wall_follow_probe_dist
	if _ray_clear(global_position, probe_to, _move_mask, exclude):
		return tangent

	# Try the other side
	var tangent2: Vector2 = nrm.rotated(float(-_nav_side) * PI * 0.5).normalized()
	var probe_to2: Vector2 = global_position + tangent2 * wall_follow_probe_dist
	if _ray_clear(global_position, probe_to2, _move_mask, exclude):
		_nav_side *= -1
		return tangent2

	# If both are blocked, rotate a bit and hope to escape a corner
	return tangent.rotated(float(_nav_side) * deg_to_rad(25.0)).normalized()


# ------------------------------------------------------------
# Ray helpers (IMPORTANT: no player/enemy layer involvement)
# ------------------------------------------------------------
func _ray_clear(a: Vector2, b: Vector2, mask: int, exclude: Array[RID]) -> bool:
	var space_state: PhysicsDirectSpaceState2D = get_world_2d().direct_space_state
	var q: PhysicsRayQueryParameters2D = PhysicsRayQueryParameters2D.create(a, b)
	q.collision_mask = mask
	q.exclude = exclude
	var hit: Dictionary = space_state.intersect_ray(q)
	return hit.is_empty()


func _ray_hit(a: Vector2, b: Vector2, mask: int, exclude: Array[RID]) -> Dictionary:
	var space_state: PhysicsDirectSpaceState2D = get_world_2d().direct_space_state
	var q: PhysicsRayQueryParameters2D = PhysicsRayQueryParameters2D.create(a, b)
	q.collision_mask = mask
	q.exclude = exclude
	return space_state.intersect_ray(q)


func _build_exclude_rids() -> Array[RID]:
	var ex: Array[RID] = [get_rid()]

	# exclude player body + hurtbox so LOS/path rays don't “hit the target”
	if player != null and is_instance_valid(player):
		if player is CollisionObject2D:
			ex.append((player as CollisionObject2D).get_rid())

		var hb := player.get_node_or_null("Hurtbox") as Area2D
		if hb != null:
			ex.append(hb.get_rid())

	return ex


func _layer_bit(layer_index_1based: int) -> int:
	return (1 << (layer_index_1based - 1))


func _refresh_masks() -> void:
	# We avoid world layer 1 in rays because player/enemies are also on layer 1.
	# Walls/cover also live on 9/10/11, so those are enough for movement/LOS reasoning.
	var fallback_cover: int = _layer_bit(cover_full_layer) | _layer_bit(cover_window_layer) | _layer_bit(cover_half_layer)

	var cover_from_senses: int = 0
	if _senses != null:
		cover_from_senses = int(_senses.cover_mask())

	var cover_all: int = (fallback_cover | cover_from_senses)
	if cover_all == 0:
		cover_all = fallback_cover

	# movement blocks on all cover
	_move_mask = (move_mask_override if move_mask_override != 0 else cover_all)

	# LOS rules:
	# - melee: full + window block LOS
	# - shooter: only full blocks LOS (window can be “shoot-through” later)
	_los_mask_melee = _layer_bit(cover_full_layer) | _layer_bit(cover_window_layer)
	_los_mask_shooter = _layer_bit(cover_full_layer)

	if los_mask_override != 0:
		_los_mask_melee = los_mask_override
		_los_mask_shooter = los_mask_override


func _escape_if_inside_wall() -> void:
	# If we spawned inside a wall tile, relocate.
	if not _point_blocked(global_position):
		return

	for i in range(maxi(1, spawn_escape_tries)):
		var ang: float = randf() * TAU
		var r: float = lerpf(20.0, spawn_escape_radius, randf())
		var p: Vector2 = global_position + Vector2.RIGHT.rotated(ang) * r
		if not _point_blocked(p):
			global_position = p
			_nav_last_pos = p
			return


func _point_blocked(p: Vector2) -> bool:
	var space_state: PhysicsDirectSpaceState2D = get_world_2d().direct_space_state
	var q := PhysicsPointQueryParameters2D.new()
	q.position = p
	q.collision_mask = _move_mask
	q.collide_with_bodies = true
	q.collide_with_areas = true
	q.exclude = [get_rid()]
	var res: Array = space_state.intersect_point(q, 1)
	return not res.is_empty()


# -----------------------
# Elite
# -----------------------
func make_elite() -> void:
	if spec == null or is_elite:
		return

	is_elite = true
	max_hp *= spec.elite_hp_mult
	hp = max_hp

	speed *= spec.elite_speed_mult
	_base_speed = speed

	var spr: CanvasItem = get_node_or_null("Sprite2D") as CanvasItem
	if spr != null:
		spr.modulate = spec.elite_tint


# -----------------------
# Effects / CC
# -----------------------
func apply_knockback(force: Vector2) -> void:
	knockback_vel += force

func apply_stun(seconds: float) -> void:
	stun_time = maxf(stun_time, seconds)

func apply_speed_buff(mult: float, duration: float) -> void:
	if mult <= 1.0 or duration <= 0.0:
		return
	_speed_mul = maxf(_speed_mul, mult)
	_speed_mul_time = maxf(_speed_mul_time, duration)


# -----------------------
# Hitbox -> Leech
# -----------------------
func _on_hitbox_area_entered(a: Area2D) -> void:
	_leech.on_hitbox_area_entered(a)

func _on_hitbox_area_exited(a: Area2D) -> void:
	_leech.on_hitbox_area_exited(a)


