extends RefCounted
class_name EnemySenses

var _enemy: Enemy = null

func setup(enemy: Enemy) -> void:
	_enemy = enemy

func cover_mask() -> int:
	if _enemy == null or not is_instance_valid(_enemy):
		return 0
	if _enemy.spec == null:
		return 0
	return int(_enemy.spec.tactical_cover_mask)

func make_exclude_rids() -> Array[RID]:
	var ex: Array[RID] = []
	if _enemy == null or not is_instance_valid(_enemy):
		return ex

	# exclude self body
	ex.append(_enemy.get_rid())

	# exclude own hitbox
	var hb: Area2D = _enemy.get_node_or_null("Hitbox") as Area2D
	if hb != null:
		ex.append(hb.get_rid())

	# exclude player body + hurtbox (prevents weird "blocked by target")
	if _enemy.player != null and is_instance_valid(_enemy.player):
		var p := _enemy.player
		if p is CollisionObject2D:
			ex.append((p as CollisionObject2D).get_rid())

		var phb: Area2D = p.get_node_or_null("Hurtbox") as Area2D
		if phb != null:
			ex.append(phb.get_rid())

	return ex

func has_los_to_player() -> bool:
	if _enemy == null or not is_instance_valid(_enemy):
		return false
	if _enemy.player == null or not is_instance_valid(_enemy.player):
		return false

	var mask: int = cover_mask()
	if mask == 0:
		return true

	var w: World2D = _enemy.get_world_2d()
	if w == null:
		return true

	var space: PhysicsDirectSpaceState2D = w.direct_space_state
	var params := PhysicsRayQueryParameters2D.new()
	params.from = _enemy.global_position
	params.to = _enemy.player.global_position
	params.collision_mask = mask
	params.exclude = make_exclude_rids()

	var hit: Dictionary = space.intersect_ray(params)
	return hit.is_empty()

func ray_clear(a: Vector2, b: Vector2) -> bool:
	var mask: int = cover_mask()
	if mask == 0:
		return true

	var w: World2D = _enemy.get_world_2d()
	if w == null:
		return true

	var space: PhysicsDirectSpaceState2D = w.direct_space_state
	var params := PhysicsRayQueryParameters2D.new()
	params.from = a
	params.to = b
	params.collision_mask = mask
	params.exclude = make_exclude_rids()

	var hit: Dictionary = space.intersect_ray(params)
	return hit.is_empty()

func point_blocked(p: Vector2) -> bool:
	var mask: int = cover_mask()
	if mask == 0:
		return false

	var w: World2D = _enemy.get_world_2d()
	if w == null:
		return false

	var space: PhysicsDirectSpaceState2D = w.direct_space_state
	var params := PhysicsPointQueryParameters2D.new()
	params.position = p
	params.collision_mask = mask
	params.collide_with_areas = true
	params.collide_with_bodies = true
	params.exclude = make_exclude_rids()

