gdscript
extends RefCounted
class_name EnemyNavigator

var _enemy: Enemy
var _senses: EnemySenses

# state
var _following: bool = false
var _side: int = 1 # 1=left, -1=right
var _wall_normal: Vector2 = Vector2.ZERO
var _commit_time: float = 0.0

var _best_dist: float = 999999.0
var _since_best: float = 0.0

var _last_pos: Vector2 = Vector2.ZERO
var _stuck_time: float = 0.0

func setup(enemy: Enemy, senses: EnemySenses) -> void:
	_enemy = enemy
	_senses = senses
	_last_pos = enemy.global_position

func reset() -> void:
	_following = false
	_commit_time = 0.0
	_wall_normal = Vector2.ZERO
	_best_dist = 999999.0
	_since_best = 0.0
	_stuck_time = 0.0

func apply(delta: float, to_player: Vector2, dist: float, speed: float, cover_mask: int) -> Vector2:
	if _enemy == null or not is_instance_valid(_enemy):
		return to_player * speed
	if _enemy.player == null or not is_instance_valid(_enemy.player):
		return to_player * speed
	if to_player == Vector2.ZERO:
		return Vector2.ZERO

	# no cover world => no pathing needed
	if cover_mask == 0:
		reset()
		return to_player * speed

	var ex: Array[RID] = _senses.make_exclude_rids()

	# direct line is clear => stop wall-follow
	if _ray_clear(_enemy.global_position, _enemy.player.global_position, cover_mask, ex):
		reset()
		return to_player * speed

	# update stuck tracking
	var moved: float = _enemy.global_position.distance_to(_last_pos)
	_last_pos = _enemy.global_position

	var min_move: float = float(_enemy.wall_follow_min_move_px_per_sec) * delta
	if moved < min_move:
		_stuck_time += delta
	else:
		_stuck_time = maxf(_stuck_time - delta, 0.0)

	if _stuck_time >= _enemy.wall_follow_stuck_flip_time:
		_stuck_time = 0.0
		_side *= -1
		_commit_time = 0.0

	# progress tracking: if we aren't getting closer for too long, flip side
	if dist < _best_dist - 6.0:
		_best_dist = dist
		_since_best = 0.0
	else:
		_since_best += delta
		if _since_best > 2.8:
			_since_best = 0.0
			_side *= -1
			_commit_time = 0.0

	# start follow
	if not _following:
		_following = true
		_commit_time = 0.0
		_wall_normal = _initial_wall_normal(cover_mask, ex, to_player)
		_pick_side(to_player)

	# wall-follow step
	return _wall_follow_step(delta, to_player, speed, cover_mask, ex)

# -------------------------
# internals
# -------------------------

func _wall_follow_step(delta: float, to_player: Vector2, speed: float, mask: int, ex: Array[RID]) -> Vector2:
	if _commit_time > 0.0:
		_commit_time = maxf(_commit_time - delta, 0.0)

	# If normal is missing, reacquire
	if _wall_normal == Vector2.ZERO or _commit_time <= 0.0:
		_wall_normal = _initial_wall_normal(mask, ex, to_player)
		_commit_time = _enemy.wall_follow_commit_time

	# Tangent direction to follow the wall
	var tangent: Vector2 = _wall_normal.rotated(float(_side) * PI * 0.5).normalized()
	if tangent == Vector2.ZERO:
		return to_player * speed

	# "hand" direction: toward the wall
	var toward_wall: Vector2 = (-_wall_normal).normalized()
	var hand_hit: Dictionary = _ray_hit(
		_enemy.global_position,
		_enemy.global_position + toward_wall * _enemy.wall_follow_hand_probe_dist,
		mask,
		ex
	)

	var has_wall_contact: bool = not hand_hit.is_empty()
	if has_wall_contact:
		# Update wall normal from the hand probe (this is how we turn corners correctly)
		_wall_normal = (hand_hit.get("normal", _wall_normal) as Vector2)
	else:
		# Door/gap detection: our hand lost the wall => step outward through gap
		# outward is "toward_wall" (since toward_wall points where wall USED to be)
		var out_bias: Vector2 = toward_wall * _enemy.wall_follow_gap_exit_bias
		var vgap: Vector2 = (tangent + out_bias).normalized()
		if vgap != Vector2.ZERO:
			return vgap * speed

	# Forward probe: if we are about to hit a corner, update normal from forward hit
	var fwd_hit: Dictionary = _ray_hit(
		_enemy.global_position,
		_enemy.global_position + tangent * _enemy.wall_follow_probe_dist,
		mask,
		ex
	)
	if not fwd_hit.is_empty():
		_wall_normal = (fwd_hit.get("normal", _wall_normal) as Vector2)
		tangent = _wall_normal.rotated(float(_side) * PI * 0.5).normalized()

	# Keep-off bias (prevents grinding into wall)
	var keep_off: Vector2 = _wall_normal.normalized() * _enemy.wall_follow_keep_off_bias

	var v: Vector2 = (tangent + keep_off).normalized()
	if v == Vector2.ZERO:
		v = tangent

	return v * speed

func _initial_wall_normal(mask: int, ex: Array[RID], to_player: Vector2) -> Vector2:
	var hit: Dictionary = _ray_hit(_enemy.global_position, _enemy.player.global_position, mask, ex)
	if not hit.is_empty():
		var n: Vector2 = hit.get("normal", Vector2.ZERO) as Vector2
		if n != Vector2.ZERO:
			return n.normalized()

	# fallback
	return (-to_player).normalized()

func _pick_side(to_player: Vector2) -> void:
	# choose the side that has better dot toward goal initially (less stupid first choice)
	var left: Vector2 = _wall_normal.rotated(PI * 0.5).normalized()
	var right: Vector2 = _wall_normal.rotated(-PI * 0.5).normalized()

	var dl: float = left.dot(to_player)
	var dr: float = right.dot(to_player)

	_side = (1 if dl >= dr else -1)

func _ray_clear(a: Vector2, b: Vector2, mask: int, ex: Array[RID]) -> bool:
	var w: World2D = _enemy.get_world_2d()
	if w == null:
		return true
	var space: PhysicsDirectSpaceState2D = w.direct_space_state
	var params := PhysicsRayQueryParameters2D.new()
	params.from = a
	params.to = b
	params.collision_mask = mask
	params.exclude = ex
	var hit: Dictionary = space.intersect_ray(params)
	return hit.is_empty()

func _ray_hit(a: Vector2, b: Vector2, mask: int, ex: Array[RID]) -> Dictionary:
	var w: World2D = _enemy.get_world_2d()
	if w == null:
		return {}
	var space: PhysicsDirectSpaceState2D = w.direct_space_state
	var params := PhysicsRayQueryParameters2D.new()
	params.from = a
	params.to = b
	params.collision_mask = mask
	params.exclude = ex
	return space.intersect_ray(params)
